"""Compile the additive-conformal LCB into a soft-floor allocation policy."""

from __future__ import annotations
import argparse,json,resource,time
from datetime import datetime,timezone
from pathlib import Path
import numpy as np
import torch
import torch.nn.functional as F
import yaml
from scripts.run_worldsim_v67_p109_directional_actor_uncertainty import DirectionalActorGaussian
from scripts.run_worldsim_v67_p199_joint_horizon_reliability_copula import JointHorizonCopula,_load_density
from scripts.run_worldsim_v67_p203_monotone_beta_joint_calibration import MonotoneBetaCalibration
from scripts.run_worldsim_v67_p233_monotone_prefix_reliability_surface import _dataset
from scripts.run_worldsim_v67_p276_epistemic_lcb_lagrangian_policy import EpistemicLCBLagrangianPolicy,_optimal_budget,_evaluate
from scripts.run_worldsim_v67_p283_conformalized_epistemic_lcb_surface import ConformalizedLCBSurface


def _rename(row):
 row['mean_budget_change_low_to_high_tolerance']=row.pop('mean_budget_change_low_to_high_beta');return row


def main():
 p=argparse.ArgumentParser();p.add_argument('--config',type=Path,required=True);p.add_argument('--runs-root',type=Path,required=True);p.add_argument('--run-id',required=True);a=p.parse_args();c=yaml.safe_load(a.config.read_text());d=a.runs_root/'worldsim_v67'/c['task_id']/a.run_id;d.mkdir(parents=True,exist_ok=False);(d/'resolved.yaml').write_text(yaml.safe_dump(c,sort_keys=False));started=time.monotonic();torch.manual_seed(int(c['seed']));torch.cuda.reset_peak_memory_stats();ens=torch.load(a.runs_root/c['frozen_p126']['run']/c['frozen_p126']['artifact'],map_location='cuda');members=[]
 for state in ens['member_state_dicts']:
  member=DirectionalActorGaussian(20,ens['hidden_dimensions']).cuda();member.load_state_dict(state);members.append(member.eval())
 density,fd=_load_density(a.runs_root/c['frozen_p182']['run']/c['frozen_p182']['artifact']);p199=torch.load(a.runs_root/c['frozen_p199']['run']/c['frozen_p199']['artifact'],map_location='cuda');copula=JointHorizonCopula(8,p199['hidden_dimensions'],4).cuda();copula.load_state_dict(p199['model_state_dict']);copula.eval();p203=torch.load(a.runs_root/c['frozen_p203']['run']/c['frozen_p203']['artifact'],map_location='cuda');calibrator=MonotoneBetaCalibration().cuda();calibrator.load_state_dict(p203['model_state_dict']);calibrator.eval();h=np.asarray(c['horizons_seconds'],np.float32);anchors=np.asarray(c['feature_anchor_budgets'],np.float32);common=(members,ens,density,fd,p199,copula,calibrator,h);tail=(float(c['boundary_state_cost']['clearance_floor_m']),int(c['teacher']['monte_carlo_samples']),int(c['seed']),float(c['teacher']['ignored_future_marginal_probability']));sf,_,_,scenes,_=_dataset(a.runs_root/c['source_rows']['run']/c['source_rows']['artifact'],*common,anchors,*tail);f201,_,_,_,_=_dataset(a.runs_root/c['p201_rows']['run']/c['p201_rows']['artifact'],*common,anchors,*tail);fresh,_,_,_,_=_dataset(a.runs_root/c['fresh_rows']['run']/c['fresh_rows']['artifact'],*common,anchors,*tail);artifact=torch.load(a.runs_root/c['frozen_p284']['run']/c['frozen_p284']['artifact'],map_location='cuda');teacher=ConformalizedLCBSurface(int(artifact['context_width']),int(artifact['budget_rate_knot_count']),int(artifact['tolerance_rate_knot_count'])).cuda();teacher.load_state_dict(artifact['model_state_dict']);teacher.eval();domain=np.asarray(c['shadow_price_domain'],np.float32);prices=np.exp(np.linspace(np.log(domain[0]),np.log(domain[1]),int(c['training_price_count']),dtype=np.float32));hp=np.sqrt(prices[:-1]*prices[1:]);mean=.5*(np.log(domain[0])+np.log(domain[1]));scale=.5*(np.log(domain[1])-np.log(domain[0]));price_z=((np.log(prices)-mean)/scale).astype(np.float32);hprice_z=((np.log(hp)-mean)/scale).astype(np.float32);alphas=np.asarray(c['training_alpha_fairness'],np.float32);ha=np.asarray(c['heldout_alpha_fairness'],np.float32);tolerances=np.asarray(c['training_risk_tolerances'],np.float32);ht=np.asarray(c['heldout_risk_tolerances'],np.float32);td=np.asarray(artifact['risk_tolerance_domain'],np.float32);tol_z=(2*(tolerances-td[0])/(td[1]-td[0])-1).astype(np.float32);htol_z=(2*(ht-td[0])/(td[1]-td[0])-1).astype(np.float32);floors=np.asarray(c['training_final_reliability_floors'],np.float32);hf=np.asarray(c['heldout_final_reliability_floors'],np.float32);floor_domain=np.asarray(c['final_reliability_floor_domain'],np.float32);floor_z=(2*(floors-floor_domain[0])/(floor_domain[1]-floor_domain[0])-1).astype(np.float32);hfloor_z=(2*(hf-floor_domain[0])/(floor_domain[1]-floor_domain[0])-1).astype(np.float32);grid_z=np.linspace(-1,1,int(c['teacher_budget_grid_count']),dtype=np.float32);epsilon=float(c['alpha_utility_epsilon']);penalty=float(c['final_reliability_shortfall_penalty']);chunk=int(c['teacher_chunk_size']);source_target=_optimal_budget(teacher,sf,alphas,tolerances,tol_z,floors,prices,grid_z,epsilon,penalty,chunk);target201=_optimal_budget(teacher,f201,ha,ht,htol_z,hf,hp,grid_z,epsilon,penalty,chunk);fresh_target=_optimal_budget(teacher,fresh,ha,ht,htol_z,hf,hp,grid_z,epsilon,penalty,chunk);dev=scenes%int(c['split']['development_scene_modulus'])==int(c['split']['development_scene_remainder']);source_heldout=_optimal_budget(teacher,sf[dev],ha,ht,htol_z,hf,hp,grid_z,epsilon,penalty,chunk);x=torch.from_numpy(sf).cuda();target=torch.from_numpy(source_target).cuda();pz=torch.from_numpy(price_z).cuda();at=torch.from_numpy(alphas).cuda();tt=torch.from_numpy(tol_z).cuda();ft=torch.from_numpy(floor_z).cuda();train_idx=torch.from_numpy(np.flatnonzero(~dev)).cuda();m=c['student'];student=EpistemicLCBLagrangianPolicy(int(m['width']),int(m['rate_knot_count'])).cuda();opt=torch.optim.AdamW(student.parameters(),lr=float(m['learning_rate']),weight_decay=float(m['weight_decay']));last=0.
 for step in range(int(m['steps'])):
  idx=train_idx[torch.randint(len(train_idx),(int(m['batch_size']),),device='cuda')];ai=torch.randint(len(alphas),(len(idx),),device='cuda');ti=torch.randint(len(tolerances),(len(idx),),device='cuda');li=torch.randint(len(floors),(len(idx),),device='cuda');pi=torch.randint(len(prices),(len(idx),),device='cuda');prediction=student(x[idx],pz[pi],at[ai],tt[ti],ft[li]);loss=F.l1_loss(prediction,target[idx,ai,ti,li,pi]);opt.zero_grad(set_to_none=True);loss.backward();opt.step();last=float(loss.detach())
  if step%500==0:print(f'P285 additive LCB policy step={step+1} budget_mae={last:.7f}',flush=True)
 source=_rename(_evaluate(student,teacher,sf[dev],source_heldout,ha,ht,htol_z,hf,hfloor_z,hp,hprice_z,epsilon,penalty));r201=_rename(_evaluate(student,teacher,f201,target201,ha,ht,htol_z,hf,hfloor_z,hp,hprice_z,epsilon,penalty));fresh_result=_rename(_evaluate(student,teacher,fresh,fresh_target,ha,ht,htol_z,hf,hfloor_z,hp,hprice_z,epsilon,penalty));decision=c['decision'];checks={'P201_budget_fidelity':r201['normalized_log_budget_MAE']<=float(decision['maximum_P201_normalized_log_budget_MAE']),'P201_frozen_additive_LCB_floor_regret':r201['mean_frozen_LCB_floor_Lagrangian_utility_regret']<=float(decision['maximum_P201_mean_frozen_LCB_floor_Lagrangian_utility_regret'])};verdict=c['verdict_on_pass'] if all(checks.values()) else c['verdict_on_failure'];torch.save({'model_state_dict':student.state_dict(),'width':m['width'],'rate_knot_count':m['rate_knot_count'],'shadow_price_log_mean':mean,'shadow_price_log_scale':scale,'floor_domain':floor_domain,'risk_tolerance_domain':td,'alpha_utility_epsilon':epsilon,'shortfall_penalty':penalty,'base_model':c['frozen_p284']},d/c['model_artifact']);summary={'schema_version':c['output_schema_version'],'task_id':c['task_id'],'hypothesis_id':c['hypothesis_id'],'status':'done','verdict':verdict,'role':c['role'],'training':{'trajectory_count':int((~dev).sum()),'final_normalized_log_budget_mae':last},'source_development':source,'P201_post_hoc_development':r201,'P243_consumed_descriptive':fresh_result,'decision_checks':checks,'resources':{'gpu':torch.cuda.get_device_name(0),'peak_gpu_memory_gib':torch.cuda.max_memory_allocated()/2**30,'peak_rss_gib':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/2**20,'wall_seconds':time.monotonic()-started},'claim_boundary':c['claim_boundary']};(d/'summary.json').write_text(json.dumps(summary,indent=2)+'\n');(d/'status.json').write_text(json.dumps({'status':'done','completed_at_utc':datetime.now(timezone.utc).isoformat()},indent=2)+'\n');print(json.dumps({'run_dir':str(d),**summary},indent=2))


if __name__=='__main__':main()
